local Players=game:GetService("Players")local Workspace=game:GetService("Workspace")local LocalPlayer=Players.LocalPlayer local ScreenGui=Instance.new("ScreenGui")ScreenGui.Name="EventGui"ScreenGui.ResetOnSpawn=false ScreenGui.Parent=LocalPlayer:WaitForChild("PlayerGui")local MainFrame=Instance.new("Frame")MainFrame.Size=UDim2.new(0,220,0,180)MainFrame.Position=UDim2.new(0.5,-110,0.5,-90)MainFrame.BackgroundColor3=Color3.fromRGB(0,0,0)MainFrame.BorderSizePixel=2 MainFrame.BorderColor3=Color3.fromRGB(60,60,60)MainFrame.Active=true MainFrame.Draggable=true MainFrame.Parent=ScreenGui local TitleLabel=Instance.new("TextLabel")TitleLabel.Size=UDim2.new(0.6,0,0,35)TitleLabel.Position=UDim2.new(0,5,0,0)TitleLabel.BackgroundTransparency=1 TitleLabel.Text="roblox event 20"TitleLabel.TextColor3=Color3.fromRGB(255,255,255)TitleLabel.TextScaled=true TitleLabel.Font=Enum.Font.GothamBold TitleLabel.Parent=MainFrame local HatTabBtn=Instance.new("TextButton")HatTabBtn.Size=UDim2.new(0,30,0,30)HatTabBtn.Position=UDim2.new(0.65,0,0,2)HatTabBtn.BackgroundColor3=Color3.fromRGB(50,50,50)HatTabBtn.BorderSizePixel=1 HatTabBtn.Text="🎩"HatTabBtn.TextScaled=true HatTabBtn.Parent=MainFrame local AnimalTabBtn=Instance.new("TextButton")AnimalTabBtn.Size=UDim2.new(0,30,0,30)AnimalTabBtn.Position=UDim2.new(0.82,0,0,2)AnimalTabBtn.BackgroundColor3=Color3.fromRGB(30,30,30)AnimalTabBtn.BorderSizePixel=1 AnimalTabBtn.Text="🐱"AnimalTabBtn.TextScaled=true AnimalTabBtn.Parent=MainFrame local HatContainer=Instance.new("Frame")HatContainer.Size=UDim2.new(1,0,0,120)HatContainer.Position=UDim2.new(0,0,0,45)HatContainer.BackgroundTransparency=1 HatContainer.Visible=true HatContainer.Parent=MainFrame local TpHatBtn=Instance.new("TextButton")TpHatBtn.Size=UDim2.new(0.9,0,0,45)TpHatBtn.Position=UDim2.new(0.05,0,0,5)TpHatBtn.BackgroundColor3=Color3.fromRGB(30,30,30)TpHatBtn.BorderSizePixel=1 TpHatBtn.Text="tp hat [OFF]"TpHatBtn.TextColor3=Color3.fromRGB(255,0,0)TpHatBtn.TextScaled=true TpHatBtn.Font=Enum.Font.GothamBold TpHatBtn.Parent=HatContainer local CountLabel=Instance.new("TextLabel")CountLabel.Size=UDim2.new(0.9,0,0,35)CountLabel.Position=UDim2.new(0.05,0,0,60)CountLabel.BackgroundTransparency=1 CountLabel.Text="Objects: 0"CountLabel.TextColor3=Color3.fromRGB(200,200,200)CountLabel.TextScaled=true CountLabel.Font=Enum.Font.Gotham CountLabel.Parent=HatContainer local AnimalContainer=Instance.new("Frame")AnimalContainer.Size=UDim2.new(1,0,0,120)AnimalContainer.Position=UDim2.new(0,0,0,45)AnimalContainer.BackgroundTransparency=1 AnimalContainer.Visible=false AnimalContainer.Parent=MainFrame local TpAnimalsBtn=Instance.new("TextButton")TpAnimalsBtn.Size=UDim2.new(0.9,0,0,50)TpAnimalsBtn.Position=UDim2.new(0.05,0,0,20)TpAnimalsBtn.BackgroundColor3=Color3.fromRGB(40,40,40)TpAnimalsBtn.BorderSizePixel=1 TpAnimalsBtn.Text="tp animals 👆"TpAnimalsBtn.TextColor3=Color3.fromRGB(255,255,255)TpAnimalsBtn.TextScaled=true TpAnimalsBtn.Font=Enum.Font.GothamBold TpAnimalsBtn.Parent=AnimalContainer HatTabBtn.MouseButton1Click:Connect(function()HatContainer.Visible=true AnimalContainer.Visible=false HatTabBtn.BackgroundColor3=Color3.fromRGB(50,50,50)AnimalTabBtn.BackgroundColor3=Color3.fromRGB(30,30,30)end)AnimalTabBtn.MouseButton1Click:Connect(function()HatContainer.Visible=false AnimalContainer.Visible=true AnimalTabBtn.BackgroundColor3=Color3.fromRGB(50,50,50)HatTabBtn.BackgroundColor3=Color3.fromRGB(30,30,30)end)local isTpHatActive=false local rescueFolder=Workspace:FindFirstChild("RescueEventObjects")local npcsFolder=Workspace:FindFirstChild("NPCs")local function updateCount()if rescueFolder then CountLabel.Text="Objects: "..tostring(#rescueFolder:GetChildren())else CountLabel.Text="Objects: Folder Not Found"end end if rescueFolder then updateCount()rescueFolder.ChildAdded:Connect(updateCount)rescueFolder.ChildRemoved:Connect(updateCount)end local function getRoot(char)return char and(char:FindFirstChild("HumanoidRootPart")or char:FindFirstChild("Torso"))end TpHatBtn.MouseButton1Click:Connect(function()isTpHatActive=not isTpHatActive if isTpHatActive then TpHatBtn.Text="tp hat [ON]"TpHatBtn.TextColor3=Color3.fromRGB(0,255,0)task.spawn(function()while isTpHatActive do local character=LocalPlayer.Character local hrp=getRoot(character)if hrp and rescueFolder then local items=rescueFolder:GetChildren()if #items>0 then local originalCFrame=hrp.CFrame for _,item in ipairs(items)do if not isTpHatActive then break end local targetPart=item:IsA("BasePart")and item or item:FindFirstChildWhichIsA("BasePart")if targetPart then hrp.CFrame=targetPart.CFrame task.wait(0.2)end end if isTpHatActive then hrp.CFrame=originalCFrame end end end task.wait(0.5)end end)else TpHatBtn.Text="tp hat [OFF]"TpHatBtn.TextColor3=Color3.fromRGB(255,0,0)end end)TpAnimalsBtn.MouseButton1Click:Connect(function()local character=LocalPlayer.Character local hrp=getRoot(character)if hrp and npcsFolder then local closestNpc=nil local shortestDistance=math.huge for _,npc in ipairs(npcsFolder:GetChildren())do local npcRoot=getRoot(npc)or(npc:IsA("BasePart")and npc)or npc:FindFirstChildWhichIsA("BasePart")if npcRoot then local distance=(hrp.Position-npcRoot.Position).Magnitude if distance<shortestDistance then shortestDistance=distance closestNpc=npcRoot end end end if closestNpc then hrp.CFrame=closestNpc.CFrame end end end)
